<?php
require_once __DIR__ . '/includes/admin.php';
$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));
if(isset($_GET['export']) && $_GET['export']==='csv'){
    $q=$pdo->prepare('SELECT p.kode_peminjaman,u.nama,u.nis,u.kelas,p.tanggal_pengajuan,p.tanggal_pinjam,p.tanggal_rencana_kembali,p.tanggal_realisasi_kembali,p.status,p.keperluan,COALESCE(pe.terlambat_hari,0) terlambat_hari,COALESCE(pe.denda,0) denda FROM peminjaman p JOIN users u ON u.id=p.user_id LEFT JOIN pengembalian pe ON pe.peminjaman_id=p.id WHERE DATE(p.tanggal_pengajuan) BETWEEN ? AND ? ORDER BY p.id DESC');$q->execute([$from,$to]);
    header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename=laporan-sipala-'.date('Ymd-His').'.csv');$out=fopen('php://output','w');fputcsv($out,['Kode','Nama','NIS','Kelas','Pengajuan','Pinjam','Rencana Kembali','Realisasi Kembali','Status','Keperluan','Terlambat (hari)','Denda']);while($r=$q->fetch(PDO::FETCH_ASSOC))fputcsv($out,$r);fclose($out);exit;
}
$q=$pdo->prepare('SELECT p.kode_peminjaman,u.nama,u.nis,u.kelas,p.tanggal_pengajuan,p.tanggal_pinjam,p.tanggal_rencana_kembali,p.tanggal_realisasi_kembali,p.status,p.keperluan,COALESCE(pe.terlambat_hari,0) terlambat_hari,COALESCE(pe.denda,0) denda FROM peminjaman p JOIN users u ON u.id=p.user_id LEFT JOIN pengembalian pe ON pe.peminjaman_id=p.id WHERE DATE(p.tanggal_pengajuan) BETWEEN ? AND ? ORDER BY p.id DESC');$q->execute([$from,$to]);$rows=$q->fetchAll();$totalDenda=array_sum(array_map(fn($r)=>(float)$r['denda'],$rows));
page_start('Laporan SIPALA','Rekap transaksi peminjaman dan pengembalian','laporan');
?><div class="head"><div><h2>Laporan Transaksi</h2><p>Filter berdasarkan tanggal pengajuan.</p></div><a class="btn btn-primary" href="laporan.php?from=<?=e($from)?>&to=<?=e($to)?>&export=csv">⬇️ Export CSV</a></div><div class="form-panel"><form method="get" class="grid"><div class="field"><label>Dari</label><input type="date" name="from" value="<?=e($from)?>"></div><div class="field"><label>Sampai</label><input type="date" name="to" value="<?=e($to)?>"></div><div class="form-actions" style="grid-column:1/-1"><button class="btn btn-primary">Terapkan Filter</button></div></form></div><div class="stats"><div class="stat"><small>Total Transaksi</small><strong><?=count($rows)?></strong></div><div class="stat"><small>Total Denda</small><strong>Rp <?=e(number_format($totalDenda,0,',','.'))?></strong></div></div><div class="panel"><div class="panel-title">Data Transaksi</div><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Peminjam</th><th>Jadwal</th><th>Status</th><th>Terlambat</th><th>Denda</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['kode_peminjaman'])?></b><div style="font-size:11px;color:#64748b"><?=e($r['keperluan'])?></div></td><td><?=e($r['nama'])?><div style="font-size:11px;color:#64748b"><?=e($r['nis']?:'-')?> · <?=e($r['kelas']?:'-')?></div></td><td><?=e(date('d-m-Y',strtotime($r['tanggal_pinjam']?:$r['tanggal_pengajuan'])))?> → <?=e(date('d-m-Y',strtotime($r['tanggal_rencana_kembali'])))?></td><td><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e((string)$r['terlambat_hari'])?> hari</td><td>Rp <?=e(number_format((float)$r['denda'],0,',','.'))?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6"><div class="empty">Tidak ada transaksi pada periode tersebut.</div></td></tr><?php endif;?></tbody></table></div></div><?php page_end(); ?>
